// The repaint feature module: AI Repaint — a photo regenerated by an image
// model per a prompt and style references, the result a new version in the
// original's stack. Pure data, read by both processes (features/manifests.mjs).
export default {
  id: "repaint",
  // The flag api.can() checks (shared/capabilities.mjs). Every desktop build
  // has it; the web build has the Gemini provider alone and says so with
  // aiRepaintMultiProvider (src/api/browser/bridge.js).
  capability: "aiRepaint",
  platforms: null,
  helper: null,
  web: true,
  trust: "bundled",
  contributes: {
    // The rail button, locked (not hidden) where the flag is false. The panel
    // stays mounted while the editor is open, whichever tool is active, so
    // its providers and history load once (EditorOverlay honours `mount` by
    // hand until panel mounting is table-driven).
    editorTool: { key: "ai", labelKey: "overlay.tools.repaint", unavailable: "locked", mount: "always" },
    // Settings ▸ AI Repaint: the providers and their models (SettingsOverlay
    // places it; `key` is its label under the settings namespace's `tabs`).
    settingsTab: { id: "repaint", key: "repaint" },
    // The bridge methods this feature adds to shared/ipcChannels.mjs,
    // answered by the electron entry below. The providers' credentials,
    // preferences and model listing are the host's rows (electron/ipc/ai.js):
    // the editor's text tool uses them too.
    ipc: [
      ["getAiRepaintStatus", "workspace:ai-repaint-status", 0],
      ["startAiRepaint", "workspace:ai-repaint-start", 1],
      ["pickRepaintRefs", "workspace:pick-repaint-refs", 0],
      ["listRepaintHistory", "workspace:list-repaint-history", 1],
      ["getAiStyles", "workspace:get-ai-styles", 0],
      ["saveAiStyles", "workspace:save-ai-styles", 1],
    ],
    // The MCP tools this feature adds (electron/mcp/tools/index.js appends
    // the group): repaint_asset.
    mcpTools: "./electron/mcpTools.js",
  },
  // Main-process entry, relative to this file: exports register(host).
  electron: "./electron/repaint.js",
};
